                            '  void(WINAPI *BindTexture)(uint32_t, uint32_t) = nullptr;\n'
                            '  void(WINAPI *Begin)(uint32_t) = nullptr;\n'
                            '  void(WINAPI *End)() = nullptr;\n'
                            '  void(WINAPI *TexCoord2fv)(const float *) = nullptr;\n'
                            '  void(WINAPI *TexCoord2f)(float, float) = nullptr;\n'
                            '  void(WINAPI *ArrayElement)(int32_t) = nullptr;\n'
                            '  void(WINAPI *Normal3fv)(const float *) = nullptr;\n'
                            '  void(WINAPI *Vertex3fv)(const float *) = nullptr;\n'
                            '  void(WINAPI *Vertex3f)(float, float, float) = nullptr;\n'
                            '  void(WINAPI *Enable)(uint32_t) = nullptr;\n'
