                            '    bool ok = get(wglCreateContext, "wglCreateContext") & get(wglDeleteContext, "wglDeleteContext") '
                            '&\n'
                            '              get(wglMakeCurrent, "wglMakeCurrent") & get(wglGetCurrentContext, '
                            '"wglGetCurrentContext") &\n'
                            '              get(LoadIdentity, "glLoadIdentity") & get(PushMatrix, "glPushMatrix") & '
                            'get(PopMatrix, "glPopMatrix") &\n'
                            '              get(Rotated, "glRotated") & get(Rotatef, "glRotatef") & get(Translatef, '
                            '"glTranslatef") &\n'
                            '              get(BindTexture, "glBindTexture") & get(Begin, "glBegin") & get(End, "glEnd") & '
                            'get(TexCoord2fv, "glTexCoord2fv") &\n'
                            '              get(TexCoord2f, "glTexCoord2f") & get(ArrayElement, "glArrayElement") & '
                            'get(Normal3fv, "glNormal3fv") &\n'
                            '              get(Vertex3fv, "glVertex3fv") & get(Vertex3f, "glVertex3f") & get(Enable, "glEnable") '
                            '& get(Disable, "glDisable") &\n'
                            '              get(BlendFunc, "glBlendFunc") & get(Flush, "glFlush") & get(Finish, "glFinish") & '
                            'get(Hint, "glHint") &\n'
                            '              get(EnableClientState, "glEnableClientState") & get(FrontFace, "glFrontFace") & '
                            'get(Viewport, "glViewport") &\n'
                            '              get(MatrixMode, "glMatrixMode") & get(Ortho, "glOrtho") & get(Lightfv, "glLightfv") & '
                            'get(Materialfv, "glMaterialfv") &\n'
                            '              get(Materiali, "glMateriali") & get(GenTextures, "glGenTextures") & '
                            'get(DeleteTextures, "glDeleteTextures") &\n'
                            '              get(TexParameteri, "glTexParameteri") & get(TexParameterf, "glTexParameterf") & '
                            'get(TexEnvi, "glTexEnvi") &\n'
                            '              get(TexImage2D, "glTexImage2D") & get(VertexPointer, "glVertexPointer") & '
                            'get(NormalPointer, "glNormalPointer");\n'
                            '    return ok;\n'
