                            '\n'
                            'GlApi &api() {\n'
                            '  static GlApi a;\n'
                            '  static const bool loaded = a.load();\n'
                            '  (void)loaded;\n'
                            '  return a;\n'
                            '}\n'
                            '\n'
                            '}  // namespace\n'
                            '\n'
                            'struct WglSink::Impl {\n'
                            '  GlApi &gl = api();\n'
                            '  HDC dc = nullptr;\n'
                            '  HBITMAP bm = nullptr;\n'
                            '  HGDIOBJ old = nullptr;\n'
                            '  uint16_t *bits = nullptr;\n'
                            '  HGLRC rc = nullptr;\n'
                            '  std::string why;\n'
                            "  std::map<uint32_t, uint32_t> names;   // the port's texture name -> the implementation's\n"
                            '  int32_t vsize = 3, vstride = 0, nstride = 0;\n'
                            '  uint32_t vtype = 0x1406, ntype = 0x1406;   // GL_FLOAT\n'
                            '  const float *verts = nullptr, *norms = nullptr;\n'
                            '  bool map_names = true;   // false: negative control 11 (variant 3)\n'
                            '\n'
                            '  bool cur() {\n'
                            '    if (!rc) return false;\n'
                            '    if (gl.wglGetCurrentContext() != rc) gl.wglMakeCurrent(dc, rc);\n'
                            '    return true;\n'
                            '  }\n'
                            '  uint32_t map(uint32_t id) const {\n'
                            '    if (!map_names) return id;\n'
                            '    auto it = names.find(id);\n'
                            '    return it == names.end() ? id : it->second;\n'
                            '  }\n'
                            '};\n'
                            '\n'
                            'WglSink::WglSink(int width, int height, int variant) : p_(std::make_unique<Impl>()), w_(width), '
                            'h_(height) {\n'
                            '  Impl &p = *p_;\n'
                            '  p.map_names = variant != 3;\n'
                            '  if (!p.gl.why.empty()) {\n'
                            '    p.why = p.gl.why;\n'
                            '    return;\n'
                            '  }\n'
                            "  // the original's DIB (glreplay's meta.txt of every corpus pass): 16 bpp, BI_BITFIELDS 555, "
                            'biHeight +h\n'
                            '  struct {\n'
                            '    BITMAPINFOHEADER h;\n'
                            '    DWORD m[3];\n'
                            '  } bi{};\n'
                            '  bi.h.biSize = sizeof(BITMAPINFOHEADER);\n'
                            '  bi.h.biWidth = width;\n'
                            '  bi.h.biHeight = variant == 2 ? -height : height;\n'
                            '  bi.h.biPlanes = 1;\n'
                            '  bi.h.biBitCount = 16;\n'
                            '  bi.h.biCompression = BI_BITFIELDS;\n'
                            '  bi.m[0] = variant == 1 ? 0xf800 : 0x7c00;\n'
                            '  bi.m[1] = variant == 1 ? 0x7e0 : 0x3e0;\n'
                            '  bi.m[2] = 0x1f;\n'
                            '  p.dc = CreateCompatibleDC(nullptr);\n'
                            '  void *bits = nullptr;\n'
                            '  p.bm = p.dc ? CreateDIBSection(p.dc, reinterpret_cast<BITMAPINFO *>(&bi), DIB_RGB_COLORS, &bits, '
                            'nullptr, 0) : nullptr;\n'
                            '  if (!p.bm) {\n'
                            '    p.why = "CreateDIBSection failed";\n'
                            '    return;\n'
                            '  }\n'
                            '  p.bits = static_cast<uint16_t *>(bits);\n'
                            '  p.old = SelectObject(p.dc, p.bm);\n'
                            '  PIXELFORMATDESCRIPTOR pfd{};\n'
                            '  pfd.nSize = sizeof pfd;\n'
                            '  pfd.nVersion = 1;\n'
                            '  pfd.dwFlags = PFD_DRAW_TO_BITMAP | PFD_SUPPORT_OPENGL;\n'
                            '  pfd.cColorBits = 16;\n'
                            '  const int pf = variant == 4 ? 0 : ChoosePixelFormat(p.dc, &pfd);   // variant 4: control 12 (as '
                            'if the host had none)\n'
                            '  if (!pf || !SetPixelFormat(p.dc, pf, &pfd)) p.why = "no generic pixel format for a 16-bit DIB";\n'
                            '}\n'
                            '\n'
                            'WglSink::~WglSink() {\n'
                            '  Impl &p = *p_;\n'
                            '  if (p.rc) {\n'
                            '    if (p.gl.wglGetCurrentContext() == p.rc) p.gl.wglMakeCurrent(nullptr, nullptr);\n'
                            '    p.gl.wglDeleteContext(p.rc);\n'
                            '  }\n'
                            '  if (p.dc) {\n'
                            '    if (p.old) SelectObject(p.dc, p.old);\n'
                            '    DeleteDC(p.dc);\n'
                            '  }\n'
                            '  if (p.bm) DeleteObject(p.bm);\n'
                            '}\n'
                            '\n'
                            'bool WglSink::ok() const { return p_->why.empty(); }\n'
                            'const std::string &WglSink::why() const { return p_->why; }\n'
                            'bool WglSink::has_context() const { return p_->rc != nullptr; }\n'
                            '\n'
                            'void WglSink::set_pixels(const std::vector<uint16_t> &px) {\n'
                            '  if (!p_->bits || px.size() != static_cast<size_t>(w_) * static_cast<size_t>(h_)) return;\n'
                            '  GdiFlush();\n'
                            '  std::memcpy(p_->bits, px.data(), px.size() * 2);\n'
                            '}\n'
                            '\n'
                            'void WglSink::get_pixels(std::vector<uint16_t> &px) {\n'
                            '  if (!p_->bits) return;\n'
                            '  if (p_->cur()) p_->gl.Finish();\n'
                            '  GdiFlush();\n'
                            '  px.assign(p_->bits, p_->bits + static_cast<size_t>(w_) * static_cast<size_t>(h_));\n'
                            '}\n'
                            '\n'
                            'void WglSink::set_arrays(const float *vertices, const float *normals) {\n'
                            '  Impl &p = *p_;\n'
                            '  p.verts = vertices;\n'
                            '  p.norms = normals;\n'
                            '  if (!p.cur()) return;\n'
                            '  p.gl.VertexPointer(p.vsize, p.vtype, p.vstride, p.verts);\n'
                            '  p.gl.NormalPointer(p.ntype, p.nstride, p.norms);\n'
                            '}\n'
                            '\n'
                            'void WglSink::context_create() {\n'
                            '  Impl &p = *p_;\n'
                            '  if (!ok()) return;\n'
                            '  if (p.rc) {\n'
                            '    if (p.gl.wglGetCurrentContext() == p.rc) p.gl.wglMakeCurrent(nullptr, nullptr);\n'
                            '    p.gl.wglDeleteContext(p.rc);\n'
                            '    p.names.clear();\n'
                            '  }\n'
                            '  p.rc = p.gl.wglCreateContext(p.dc);\n'
                            '  if (!p.rc) {\n'
                            '    p.why = "wglCreateContext failed";\n'
                            '    return;\n'
                            '  }\n'
                            '  p.gl.wglMakeCurrent(p.dc, p.rc);\n'
                            '}\n'
                            '\n'
                            'bool WglSink::gen_textures_mapped(int32_t n, const uint32_t *names) {\n'
                            '  Impl &p = *p_;\n'
                            '  if (!p.cur() || n <= 0) return false;\n'
                            '  std::vector<uint32_t> real(static_cast<size_t>(n), 0);\n'
                            '  p.gl.GenTextures(n, real.data());\n'
                            '  ++calls;\n'
                            '  for (int32_t i = 0; i < n; ++i) p.names[names[i]] = real[static_cast<size_t>(i)];\n'
                            '  return true;\n'
                            '}\n'
                            '\n'
                            'bool WglSink::gen_textures(int32_t n, uint32_t *names) {\n'
                            '  Impl &p = *p_;\n'
                            '  if (!p.cur()) return false;\n'
                            '  p.gl.GenTextures(n, names);\n'
                            '  ++calls;\n'
                            '  for (int32_t i = 0; i < n; ++i) p.names[names[i]] = names[i];\n'
                            '  return true;\n'
                            '}\n'
                            '\n'
                            'void WglSink::delete_textures(int32_t n, const uint32_t *names) {\n'
                            '  Impl &p = *p_;\n'
                            '  if (!p.cur() || n <= 0) return;\n'
                            '  std::vector<uint32_t> real(static_cast<size_t>(n));\n'
                            '  for (int32_t i = 0; i < n; ++i) {\n'
                            '    real[static_cast<size_t>(i)] = p.map(names[i]);\n'
                            '    p.names.erase(names[i]);\n'
                            '  }\n'
                            '  p.gl.DeleteTextures(n, real.data());\n'
                            '  ++calls;\n'
                            '}\n'
                            '\n'
                            '#define WGL_CALL(expr) \\\n'
                            '  do {                 \\\n'
                            '    if (!p_->cur()) return; \\\n'
                            '    p_->gl.expr;       \\\n'
                            '    ++calls;           \\\n'
                            '  } while (0)\n'
                            '\n'
                            'void WglSink::load_identity() { WGL_CALL(LoadIdentity()); }\n'
                            'void WglSink::push_matrix() { WGL_CALL(PushMatrix()); }\n'
                            'void WglSink::pop_matrix() { WGL_CALL(PopMatrix()); }\n'
                            'void WglSink::rotated(double a, double x, double y, double z) { WGL_CALL(Rotated(a, x, y, z)); }\n'
                            'void WglSink::rotatef(float a, float x, float y, float z) { WGL_CALL(Rotatef(a, x, y, z)); }\n'
                            'void WglSink::translatef(float x, float y, float z) { WGL_CALL(Translatef(x, y, z)); }\n'
                            'void WglSink::bind_texture(uint32_t target, uint32_t id) { WGL_CALL(BindTexture(target, '
                            'p_->map(id))); }\n'
                            'void WglSink::begin(uint32_t mode) { WGL_CALL(Begin(mode)); }\n'
                            'void WglSink::end() { WGL_CALL(End()); }\n'
                            'void WglSink::tex_coord2fv(const float *v) { WGL_CALL(TexCoord2fv(v)); }\n'
                            'void WglSink::tex_coord2f(float s, float t) { WGL_CALL(TexCoord2f(s, t)); }\n'
                            'void WglSink::array_element(int32_t i) { WGL_CALL(ArrayElement(i)); }\n'
                            'void WglSink::normal3fv(const float *v) { WGL_CALL(Normal3fv(v)); }\n'
                            'void WglSink::vertex3fv(const float *v) { WGL_CALL(Vertex3fv(v)); }\n'
                            'void WglSink::vertex3f(float x, float y, float z) { WGL_CALL(Vertex3f(x, y, z)); }\n'
                            'void WglSink::enable(uint32_t cap) { WGL_CALL(Enable(cap)); }\n'
                            'void WglSink::disable(uint32_t cap) { WGL_CALL(Disable(cap)); }\n'
                            'void WglSink::blend_func(uint32_t s, uint32_t d) { WGL_CALL(BlendFunc(s, d)); }\n'
                            'void WglSink::flush() { WGL_CALL(Flush()); }\n'
                            'void WglSink::hint(uint32_t t, uint32_t m) { WGL_CALL(Hint(t, m)); }\n'
                            'void WglSink::enable_client_state(uint32_t a) { WGL_CALL(EnableClientState(a)); }\n'
                            'void WglSink::front_face(uint32_t m) { WGL_CALL(FrontFace(m)); }\n'
                            'void WglSink::viewport(int32_t x, int32_t y, int32_t w, int32_t h) { WGL_CALL(Viewport(x, y, w, '
                            'h)); }\n'
                            'void WglSink::matrix_mode(uint32_t m) { WGL_CALL(MatrixMode(m)); }\n'
                            'void WglSink::ortho(double l, double r, double b, double t, double n, double f) { WGL_CALL(Ortho(l, '
                            'r, b, t, n, f)); }\n'
                            'void WglSink::light(uint32_t l, uint32_t pn, const float *v) { WGL_CALL(Lightfv(l, pn, v)); }\n'
                            'void WglSink::material(uint32_t f, uint32_t pn, const float *v) { WGL_CALL(Materialfv(f, pn, v)); '
                            '}\n'
                            'void WglSink::material_shininess(uint32_t f, int32_t s) { WGL_CALL(Materiali(f, 0x1601, s)); }   // '
                            'GL_SHININESS\n'
                            'void WglSink::tex_parameteri(uint32_t t, uint32_t pn, int32_t v) { WGL_CALL(TexParameteri(t, pn, '
                            'v)); }\n'
                            'void WglSink::tex_parameterf(uint32_t t, uint32_t pn, float v) { WGL_CALL(TexParameterf(t, pn, v)); '
                            '}\n'
                            'void WglSink::tex_envi(uint32_t t, uint32_t pn, int32_t v) { WGL_CALL(TexEnvi(t, pn, v)); }\n'
                            'void WglSink::tex_image2d(uint32_t t, int32_t l, int32_t i, int32_t w, int32_t h, int32_t b, '
                            'uint32_t f, uint32_t ty,\n'
                            '                          const uint8_t *d) {\n'
                            '  WGL_CALL(TexImage2D(t, l, i, w, h, b, f, ty, d));\n'
                            '}\n'
                            'void WglSink::vertex_pointer(int32_t size, uint32_t type, int32_t stride) {\n'
                            '  p_->vsize = size;\n'
